pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, string calldata description) public {
        // keep the fuzzed caller in the admissible domain (non-zero caller)
        vm.assume(actor != address(0));

        // drive c through the public entry point as the fuzzed caller
        vm.prank(actor);
        bool ok;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: the call succeeds if and only if the caller is an admin
        // (c.isAdmin(actor) is c's public getter). The reference C satisfies this
        // for every input; the buggy version reverts even for admin callers,
        // so ok == false while c.isAdmin(actor) == true, breaking the rule.
        assertTrue(ok == c.isAdmin(actor), "oracle creation must succeed iff caller is admin");
    }
}

