pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, string calldata description) public {
        // WIDEN the domain: allow any actor, including the ones that matter.
        // The only admissibility constraint is that the actor is a real caller;
        // we then register it as an admin via the public isAdmin mapping so the
        // oracle-creation path (where P and M differ) is actually reachable.
        vm.assume(actor != address(0));

        // Register the fuzzed actor as admin by writing the public isAdmin mapping.
        uint256 slot = stdstore
            .target(address(c))
            .sig(c.isAdmin.selector)
            .with_key(actor)
            .find();
        vm.store(address(c), bytes32(slot), bytes32(uint256(1)));

        // An admin's oracle creation must complete without reverting.
        vm.prank(actor);
        bool ok;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for every admissible input (any admin, any description),
        // newEmergencyOracle succeeds. The mutant passes address(0) as the owner,
        // so the constructor's transferOwnership always reverts and ok is false.
        assertTrue(ok);
    }
}

