pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(string calldata description) public {
        // Ensure this test contract is registered as an admin in c.
        // First try a generic low-level registration (no-op if no such setter exists);
        // many C deployments grant the deployer admin in the constructor instead.
        if (!c.isAdmin(address(this))) {
            vm.prank(address(this));
            (bool regOk,) = address(c).call(
                abi.encodeWithSignature("setAdmin(address,bool)", address(this), true)
            );
            // If registration via setter is impossible, fall back to re-deploying
            // so that the constructor grants the admin role to the deployer.
            if (!regOk || !c.isAdmin(address(this))) {
                c = new C();
            }
        }

        // The caller is now registered in c.isAdmin; drive the entry point.
        vm.prank(address(this));
        bool ok;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: an admin's call to newEmergencyOracle must always succeed.
        // The mutant passes address(0) as the oracle owner, so the constructor's
        // transferOwnership reverts and ok is false.
        assertTrue(ok, "admin caller must be able to create an emergency oracle");
    }
}

