pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    event NewEmergencyOracleEv(address owner, address newOracle);

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, string calldata description) public {
        // Grant admin rights to the fuzzed actor by writing the isAdmin mapping slot directly.
        // isAdmin is the first (and only) state variable of C -> slot 0.
        bytes32 slot = keccak256(abi.encode(actor, uint256(0)));
        vm.store(address(c), slot, bytes32(uint256(1)));

        vm.prank(actor);
        // General rule: a successful call must emit NewEmergencyOracle.
        // Only the event's signature is checked (all topic/data checks wildcarded),
        // so any emission of the event satisfies it.
        vm.expectEmit(false, false, false, true, address(c));
        emit NewEmergencyOracleEv(actor, actor);
        c.newEmergencyOracle(description);

        // Single assertion: on the reference contract the call above succeeded AND emitted;
        // reaching this line implies the event was emitted. The mutant never emits, so
        // vm.expectEmit reverts inside the runner for the very same input -> failure.
        assertTrue(c.isAdmin(actor));
    }
}

