pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor, string calldata description) public {
        // keep the fuzzed actor in the admissible domain: a real, non-zero,
        // non-contract-self caller
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(bytes(description).length <= 256);

        // drive c through its only public entry with the fuzzed actor
        vm.prank(actor);
        bool ok;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: since isAdmin is only ever readable (no setter exists
        // and the constructor grants nobody), for EVERY fuzzed actor the call
        // must revert — access control fails closed and nothing is deployed or
        // announced. The reference C satisfies this for all inputs; the mutant
        // breaks it because its body no longer terminates in the
        // event-announcing successful path, so for some fuzzed input the
        // call's observable outcome (revert bool / success) diverges.
        assertTrue(ok == false || c.isAdmin(actor) == true);
    }
}

