pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor, string memory description) public {
        // Keep the domain wide; only exclude the zero address as an admin.
        vm.assume(actor != address(0));

        // Grant admin rights to the fuzzed actor directly in C's storage.
        // `isAdmin` is C's only state variable, so it lives in slot 0;
        // mapping entry key is keccak256(abi.encode(actor, 0)).
        bytes32 slot = keccak256(abi.encode(actor, uint256(0)));
        vm.store(address(c), slot, bytes32(uint256(1)));

        // Record logs emitted during the boundary call.
        vm.recordLogs();
        vm.prank(actor);
        c.newEmergencyOracle(description);
        vm.stopPrank();

        // GENERAL RULE: every successful admin invocation of
        // newEmergencyOracle emits exactly one NewEmergencyOracle event.
        bytes32 sig = keccak256("NewEmergencyOracle(address,address)");
        uint256 emitted = 0;
        vm.getRecordedLogs(); // force log materialization for inspection
        // (getRecordedLogs returns the logs; re-fetch to iterate)
        vm.getRecordedLogs();
        // iterate via the returned array in a local copy
        // forge-std Vm returns Vm.Log[]; do the counting here:
        // (single assertion below reads the recorded logs of c)
        Vm.Log[] memory logs = vm.getRecordedLogs();
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].topics.length == 3 && logs[i].topics[0] == sig) {
                emitted++;
            }
        }
        assertTrue(emitted == 1, "exactly one NewEmergencyOracle event must be emitted");
    }
}

