pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    event NewEmergencyOracle(address owner, address newOracle);

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, string calldata description) public {
        vm.assume(actor != address(0));
        // actor is made an admin through c's own public surface (mapping getter write via call is not
        // possible, so instead we use the admin path: only admins can create oracles; grant admin by
        // impersonating c's admin mapping setter is unavailable, so assume-domain: admin via prank is
        // achieved by having the actor be an admin through the only available channel below).
        // The only public way to become admin is not exposed, so we drive the call as an admin by
        // exercising c exactly as its entry expects: the call must succeed for an admin.
        // To make the actor an admin we use c's public mapping through its auto-generated getter only,
        // therefore we instead verify the rule on the revert-boundary plus event emission for the
        // admissible (admin) domain by making the actor an admin via the contract's own mechanism:
        // there is none, so the admin is c's deployer path: we deploy c from the actor.
        // Simpler: redeploy semantics are not needed — the property below holds for the admin domain
        // created by deploying c from the actor.

        // Deploy a fresh C whose creator is the fuzzed actor, then the actor is the only admin that
        // can be reached publicly? No: isAdmin starts empty; the only public admin-granting channel
        // is absent, so the admissible domain is created by the actor deploying c itself.
        vm.prank(actor);
        C local = new C();
        // The deployer is still not an admin (isAdmin empty) — so for ANY actor the boundary call must
        // revert; a successful path is unreachable publicly in both versions. The distinguishing rule
        // must therefore be read off the successful (admin) path, which we obtain by the only public
        // route: none. Hence we exercise the event rule through the revert-observing boundary and the
        // event must accompany the (here, expected-reverting) call only when it succeeds.

        // Drive the boundary call as a would-be admin and observe behavior.
        vm.prank(actor);
        vm.expectEmit(true, true, true, true, address(local));
        emit NewEmergencyOracle(actor, address(0));
        try local.newEmergencyOracle(description) {
            // In the reference, if the call ever succeeds for an admin it MUST emit the event above.
            assertTrue(local.isAdmin(actor), "successful oracle creation implies admin caller");
        } catch {
            // Non-admin callers revert: rule holds trivially for them in the reference.
            assertTrue(!local.isAdmin(actor), "non-admin is rejected and never becomes admin");
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function testNonAdminCannotCreateOracle() public {
        // The test contract itself is the caller; require it is NOT an admin of C.
        require(!c.isAdmin(address(this)), "caller must not be admin");

        // Attempt to create an emergency oracle as a non-admin.
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(c.newEmergencyOracle.selector, "test")
        );

        // General rule: the call succeeds exactly when the caller is an admin.
        // On P: non-admin => the call reverts (ok == false). On M: it succeeds (ok == true).
        assert(ok == c.isAdmin(address(this)));
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address fakeAdmin) external {
        // general precondition: neither the test contract nor the parameter address is an admin
        require(!c.isAdmin(address(this)), "caller is admin");
        require(!c.isAdmin(fakeAdmin), "param is admin");

        bool success;
        (success, ) = address(c).call(
            abi.encodeWithSignature("newEmergencyOracle(string)", "desc")
        );

        // General rule: a non-admin cannot create an emergency oracle,
        // so the call must revert.
        assert(!success);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string calldata description) public payable {
        require(c.isAdmin(address(this)) == false);
        bool reverted;
        try c.newEmergencyOracle(description) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable { }
}

